"""Write the generated files of both phone apps from content/manga/.

Reads content/manga/tokens.json (design tokens) and content/manga/copy/*.json (the text people read).

Run `python3 content/manga/generate.py` to write the files.
Run `python3 content/manga/generate.py --check` to exit 1 when a file on disk is out of date.
"""
import json
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.normpath(os.path.join(HERE, "..", ".."))
TOKENS_PATH = os.path.join(HERE, "tokens.json")
COPY_DIR = os.path.join(HERE, "copy")
SWIFT_PATH = os.path.join(REPO, "apps", "manga-ios", "App", "UI", "Generated", "TokenValues.swift")
KOTLIN_PATH = os.path.join(REPO, "apps", "manga-android", "design", "src", "main", "kotlin",
                           "live", "akidev", "manga", "design", "AkiTokenValues.kt")
COPY_SWIFT_PATH = os.path.join(REPO, "apps", "manga-ios", "App", "UI", "Generated", "Copy.swift")
COPY_KOTLIN_PATH = os.path.join(REPO, "apps", "manga-android", "design", "src", "main", "kotlin",
                                "live", "akidev", "manga", "design", "AkiCopy.kt")
HEADER = "Generated by content/manga/generate.py from content/manga/tokens.json: do not edit."
COPY_HEADER = "Generated by content/manga/generate.py from content/manga/copy/*.json: do not edit."

# These two opacities are the primary color at that opacity. The other opacities are black at that opacity.
ON_PRIMARY = ("accent", "accentSoft")

CAMEL_CASE = re.compile(r"^[a-z][a-zA-Z0-9]*$")
PLACEHOLDER = re.compile(r"\{([^{}]*)\}")
# A placeholder type in copy files, and the type name it gets in Swift and Kotlin.
TYPES = {"string": "String", "int": "Int", "double": "Double"}


def fail(message):
    print("error: " + message, file=sys.stderr)
    sys.exit(1)


def load_tokens():
    with open(TOKENS_PATH, encoding="utf-8") as f:
        return json.load(f)


def hex_digits(value):
    return value.lstrip("#").upper()


def capitalize(name):
    return name[0].upper() + name[1:]


def swift_color(value):
    if isinstance(value, dict):
        return "adaptive(0x%s, 0x%s)" % (hex_digits(value["light"]), hex_digits(value["dark"]))
    return "Color(hex: 0x%s)" % hex_digits(value)


def swift_text(tokens):
    lines = ["import SwiftUI", "", "extension Aki {"]
    for name, value in tokens["colors"].items():
        lines.append("    static let %s = %s" % (name, swift_color(value)))
    lines.append("")
    for name, value in tokens["opacities"].items():
        base = "primary" if name in ON_PRIMARY else "Color(hex: 0x000000)"
        lines.append("    static let %s = %s.opacity(%.2f)" % (name, base, value))
    lines.append("")
    for name, value in tokens["radii"].items():
        lines.append("    static let %sRadius: CGFloat = %d" % (name, value))
    lines.append("}")
    return "\n".join(["// " + HEADER] + lines) + "\n"


def kotlin_text(tokens):
    lines = [
        "package live.akidev.manga.design",
        "",
        "import androidx.compose.ui.graphics.Color",
        "import androidx.compose.ui.unit.dp",
        "",
        "internal object AkiTokenValues {",
    ]
    for name, value in tokens["colors"].items():
        if isinstance(value, dict):
            lines.append("    val light%s = Color(0xFF%s)" % (capitalize(name), hex_digits(value["light"])))
            lines.append("    val dark%s = Color(0xFF%s)" % (capitalize(name), hex_digits(value["dark"])))
        else:
            lines.append("    val %s = Color(0xFF%s)" % (name, hex_digits(value)))
    lines.append("")
    for name, value in tokens["opacities"].items():
        lines.append("    const val %sOpacity = %.2ff" % (name, value))
    lines.append("")
    for name, value in tokens["radii"].items():
        lines.append("    val %sRadius = %d.dp" % (name, value))
    lines.append("}")
    return "\n".join(["// " + HEADER] + lines) + "\n"


# Copy: each message is a list of parts. A part is ("text", words) or ("arg", name, type).
# A copy file member is one of:
#   ("text", key, parts)               a string
#   ("plural", key, one_parts, other_parts)
#   ("group", key, members)            an object one level deep


def check_name(name, where):
    if not CAMEL_CASE.match(name):
        fail("%s: '%s' must be camelCase, like 'chapterCount'" % (where, name))


def parse_message(text, where):
    parts = []
    pos = 0
    for match in PLACEHOLDER.finditer(text):
        parts.append(("text", text[pos:match.start()]))
        name, _, kind = match.group(1).partition(":")
        check_name(name, where)
        kind = kind or "string"
        if kind not in TYPES:
            fail("%s: unknown type '%s' in {%s}, use string, int or double" % (where, kind, match.group(1)))
        parts.append(("arg", name, TYPES[kind]))
        pos = match.end()
    parts.append(("text", text[pos:]))
    return parts


def args_of(parts):
    """The placeholders of a message as (name, type) pairs, each name once."""
    args = []
    for part in parts:
        if part[0] == "arg" and (part[1], part[2]) not in args:
            args.append((part[1], part[2]))
    return args


def is_plural(value):
    return isinstance(value, dict) and set(value) == {"one", "other"}


def read_plural(key, value, where):
    if not (isinstance(value["one"], str) and isinstance(value["other"], str)):
        fail("%s: 'one' and 'other' must be strings" % where)
    one = parse_message(value["one"], where + ".one")
    other = parse_message(value["other"], where + ".other")
    if set(args_of(one)) != set(args_of(other)):
        fail("%s: 'one' and 'other' must declare the same placeholders" % where)
    if ("count", "Int") not in args_of(one):
        fail("%s: a plural needs a {count:int} placeholder" % where)
    return ("plural", key, one, other)


def read_members(data, where, depth):
    members = []
    for key, value in data.items():
        path = where + "." + key
        check_name(key, path)
        if isinstance(value, str):
            members.append(("text", key, parse_message(value, path)))
        elif is_plural(value):
            members.append(read_plural(key, value, path))
        elif isinstance(value, dict) and depth == 0:
            members.append(("group", key, read_members(value, path, 1)))
        else:
            fail("%s: a value must be a string or a plural object (groups are only one level deep)" % path)
    return members


def load_areas():
    """One (area, members) pair per content/manga/copy/*.json file, in sorted order."""
    areas = []
    for file_name in sorted(os.listdir(COPY_DIR)):
        if not file_name.endswith(".json"):
            continue
        area = file_name[:-len(".json")]
        check_name(area, file_name)
        with open(os.path.join(COPY_DIR, file_name), encoding="utf-8") as f:
            try:
                data = json.load(f)
            except json.JSONDecodeError as error:
                fail("%s is not valid JSON: %s" % (file_name, error))
        areas.append((area, read_members(data, area, 0)))
    return areas


def swift_escape(text):
    return text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


def kotlin_escape(text):
    return swift_escape(text).replace("$", "\\$")


def swift_literal(parts):
    body = ""
    for part in parts:
        if part[0] == "text":
            body += swift_escape(part[1])
        else:
            body += "\\(%s)" % part[1]
    return '"%s"' % body


def kotlin_literal(parts):
    body = ""
    for part in parts:
        if part[0] == "text":
            body += kotlin_escape(part[1])
        else:
            body += "${%s}" % part[1]
    return '"%s"' % body


def swift_params(args):
    return ", ".join("_ %s: %s" % (name, kind) for name, kind in args)


def kotlin_params(args):
    return ", ".join("%s: %s" % (name, kind) for name, kind in args)


def swift_members(members, indent):
    pad = "    " * indent
    lines = []
    for member in members:
        kind, key = member[0], member[1]
        if kind == "group":
            lines.append("%senum %s {" % (pad, capitalize(key)))
            lines += swift_members(member[2], indent + 1)
            lines.append(pad + "}")
        elif kind == "text":
            parts = member[2]
            if args_of(parts):
                lines.append("%sstatic func %s(%s) -> String { %s }" % (
                    pad, key, swift_params(args_of(parts)), swift_literal(parts)))
            else:
                lines.append("%sstatic let %s = %s" % (pad, key, swift_literal(parts)))
        else:
            one, other = member[2], member[3]
            lines.append("%sstatic func %s(%s) -> String { count == 1 ? %s : %s }" % (
                pad, key, swift_params(args_of(one)), swift_literal(one), swift_literal(other)))
    return lines


def kotlin_members(members, indent):
    pad = "    " * indent
    lines = []
    for member in members:
        kind, key = member[0], member[1]
        if kind == "group":
            lines.append("%sobject %s {" % (pad, capitalize(key)))
            lines += kotlin_members(member[2], indent + 1)
            lines.append(pad + "}")
        elif kind == "text":
            parts = member[2]
            if args_of(parts):
                lines.append("%sfun %s(%s): String = %s" % (
                    pad, key, kotlin_params(args_of(parts)), kotlin_literal(parts)))
            else:
                lines.append("%sconst val %s = %s" % (pad, key, kotlin_literal(parts)))
        else:
            one, other = member[2], member[3]
            lines.append("%sfun %s(%s): String = if (count == 1) %s else %s" % (
                pad, key, kotlin_params(args_of(one)), kotlin_literal(one), kotlin_literal(other)))
    return lines


def swift_copy_text(areas):
    lines = ["enum Copy {"]
    for area, members in areas:
        lines.append("    enum %s {" % capitalize(area))
        lines += swift_members(members, 2)
        lines.append("    }")
    lines.append("}")
    return "\n".join(["// " + COPY_HEADER] + lines) + "\n"


def kotlin_copy_text(areas):
    lines = ["package live.akidev.manga.design", "", "object Copy {"]
    for area, members in areas:
        lines.append("    object %s {" % capitalize(area))
        lines += kotlin_members(members, 2)
        lines.append("    }")
    lines.append("}")
    return "\n".join(["// " + COPY_HEADER] + lines) + "\n"


def read_or_none(path):
    if not os.path.exists(path):
        return None
    with open(path, encoding="utf-8") as f:
        return f.read()


def relative(path):
    return os.path.relpath(path, REPO)


def outputs():
    tokens = load_tokens()
    areas = load_areas()
    return [
        (SWIFT_PATH, swift_text(tokens)),
        (KOTLIN_PATH, kotlin_text(tokens)),
        (COPY_SWIFT_PATH, swift_copy_text(areas)),
        (COPY_KOTLIN_PATH, kotlin_copy_text(areas)),
    ]


def main():
    files = outputs()

    if "--check" not in sys.argv:
        for path, text in files:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w", encoding="utf-8") as f:
                f.write(text)
            print("wrote", relative(path))
        return

    stale = [path for path, text in files if read_or_none(path) != text]
    for path in stale:
        print("out of date:", relative(path))
    if stale:
        sys.exit(1)
    print("generated files are up to date")


if __name__ == "__main__":
    main()
